/* ---- reviews: private notes kept on this device only (the current Worker has no reviews endpoint, so nothing is sent anywhere) ---- */
var RV={msg:'',ok:false},RW=null,RK='cuder_reviews_v2';
function rl(){try{return JSON.parse(localStorage.getItem(RK)||'[]')}catch(e){return[]}}
P.rev=function(t,L,h){CT=t;CL=L;CH=h;setTimeout(rvInit,0);return hero(t('نظرات','Reviews'),t('نظر شما برای ما مهم است','Your feedback matters'),t('نظرها فعلاً فقط روی همین دستگاه ذخیره می‌شوند و به ما ارسال نمی‌شوند. برای رساندن نظر به ما از صفحه‌ی تماس استفاده کنید.','For now, reviews are saved on this device only and are not sent to us. To reach us, use the contact page.'))+'<div class="w" id="rvw"></div>'};
function rvInit(){RW=document.getElementById('rvw');if(RW)rvDraw()}
function stars(n){return'<span class="stars" aria-label="'+n+'/5">'+'★'.repeat(n)+'☆'.repeat(5-n)+'</span>'}
function rvDraw(){if(!RW)return;var t=CT,loc=rl(),form='<div class="card"><h3>'+t('نوشتن نظر','Write a review')+'</h3><label class="fr"><small>'+t('محصول','Product')+'</small><select class="f" id="rp"><option>BizFlow</option><option>DownFlow</option><option>CUDER</option></select></label><label class="fr"><small>'+t('امتیاز','Rating')+'</small><select class="f" id="rr">'+[5,4,3,2,1].map(function(n){return'<option value="'+n+'">'+'★'.repeat(n)+'</option>'}).join('')+'</select></label>'+fr(t('نام (اختیاری)','Name (optional)'),'rn','text','','name')+'<label class="fr"><small>'+t('نظر شما (۱۰ تا ۶۰۰ نویسه)','Your review (10–600 characters)')+'</small><textarea class="f" id="rx" rows="4" maxlength="600"></textarea></label><input class="hp" id="rh" tabindex="-1" autocomplete="off" aria-hidden="true"><button class="btn" data-rv="send">'+t('ذخیره روی این دستگاه','Save on this device')+'</button></div>',
 list='<h3>'+t('نظرهای شما (فقط روی این دستگاه)','Your reviews (this device only)')+'</h3>'+(loc.length?loc.slice().reverse().map(function(r){return'<div class="rvi">'+stars(r.rating)+' <b>'+esc(r.name||t('شما','You'))+'</b> <span class="mu">'+esc(r.product)+' · '+esc(r.date)+' · '+t('خصوصی','private')+'</span><p>'+esc(r.text)+'</p><button class="btn dg sm" data-rv="del" data-id="'+r.id+'">'+t('حذف','Delete')+'</button></div>'}).join(''):'<div class="empty">'+t('هنوز نظری ننوشته‌اید.','You have not written a review yet.')+'</div>');
 RW.innerHTML='<div id="rvs" class="stt '+(RV.ok?'ok':'no')+'" role="status" aria-live="polite"'+(RV.msg?'':' hidden')+'>'+esc(RV.msg||'')+'</div><div class="acw">'+form+'<div>'+list+'</div></div>'}
function rsay(m,ok){RV.msg=m;RV.ok=!!ok;var s=document.getElementById('rvs');if(s){s.className='stt '+(ok?'ok':'no');s.textContent=m;s.hidden=!m}else rvDraw()}
document.addEventListener('click',function(e){var b=e.target.closest&&e.target.closest('[data-rv]');if(!b)return;var t=CT,a=b.dataset.rv;
 if(a=='del'){try{localStorage.setItem(RK,JSON.stringify(rl().filter(function(r){return r.id!=b.dataset.id})))}catch(x){}rvDraw();return}
 if(a=='send'){if(v('rh'))return;var tx=v('rx').trim();if(tx.length<10)return rsay(t('نظر باید حداقل ۱۰ نویسه باشد.','The review needs at least 10 characters.'));var now=Date.now(),l=rl();
  l.push({id:now,date:new Date().toISOString().slice(0,10),product:v('rp'),rating:+v('rr'),name:v('rn').trim().slice(0,60),text:tx});
  try{localStorage.setItem(RK,JSON.stringify(l));RV.msg=t('نظر روی همین دستگاه ذخیره شد. این نظر برای ما ارسال نشده و عمومی نیست.','Saved on this device. It was not sent to us and is not public.');RV.ok=true;rvDraw()}catch(x){rsay(t('ذخیره ناموفق بود؛ فضای مرورگر پر است.','Saving failed; browser storage is full.'))}}});
